  VALUE="${VALUE//\"/\\\"}"
  VALUE="${VALUE//$'\b'/\\u0008}"
  VALUE="${VALUE//$'\f'/\\u000c}"
  VALUE="${VALUE//$'\n'/\\n}"
  VALUE="${VALUE//$'\r'/\\r}"
  VALUE="${VALUE//$'\t'/\\t}"
