#!/usr/bin/env node
import fs from 'node:fs';
import process from 'node:process';

const [evidencePath, policyPath] = process.argv.slice(2);
if (!evidencePath || !policyPath) throw new Error('usage: validate-performance-evidence.mjs EVIDENCE BUDGETS');
const evidence = JSON.parse(fs.readFileSync(evidencePath, 'utf8'));
const policy = JSON.parse(fs.readFileSync(policyPath, 'utf8'));
const errors = [];
const exact = (value, keys, location) => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) { errors.push(`${location} must be an object`); return; }
  for (const key of Object.keys(value)) if (!keys.includes(key)) errors.push(`${location}.${key} is unknown`);
  for (const key of keys) if (!(key in value)) errors.push(`${location}.${key} is required`);
};
exact(policy, ['schemaVersion','fixtureId','budgets'], 'policy');
if (!Array.isArray(policy.budgets) || policy.budgets.length === 0) errors.push('policy.budgets must be a non-empty array');
for (const [index, budget] of (policy.budgets ?? []).entries()) {
  exact(budget, ['name','temperature','unit','comparison','value'], `policy.budgets[${index}]`);
  if (!['cold','warm'].includes(budget.temperature)) errors.push(`policy.budgets[${index}].temperature is invalid`);
  if (!['ms','ratio','KiB','count'].includes(budget.unit)) errors.push(`policy.budgets[${index}].unit is invalid`);
  if (!['min','max'].includes(budget.comparison)) errors.push(`policy.budgets[${index}].comparison is invalid`);
  if (!Number.isFinite(budget.value) || budget.value < 0) errors.push(`policy.budgets[${index}].value is invalid`);
}
const policyKeys = (policy.budgets ?? []).map(item => `${item.name}:${item.temperature}`);
if (new Set(policyKeys).size !== policyKeys.length) errors.push('policy budget cells must be unique');
exact(evidence, ['schemaVersion','fixtureId','scope','claimsProductionPerformance','generatedAt','runtime','measurements'], '$');
if (evidence.schemaVersion !== 1 || policy.schemaVersion !== 1) errors.push('schemaVersion must equal 1');
if (evidence.fixtureId !== policy.fixtureId) errors.push('fixtureId does not match budget policy');
if (evidence.scope !== 'hermetic-fixture' || evidence.claimsProductionPerformance !== false) errors.push('fixture evidence cannot claim production performance');
if (!Number.isFinite(Date.parse(evidence.generatedAt))) errors.push('generatedAt must be an ISO timestamp');
exact(evidence.runtime, ['node','platform','arch'], '$.runtime');
const expected = new Map(policy.budgets.map(item => [`${item.name}:${item.temperature}`, item]));
if (!Array.isArray(evidence.measurements) || evidence.measurements.length !== expected.size) errors.push('measurements must cover every budget exactly once');
const seen = new Set();
for (const [index, item] of (evidence.measurements ?? []).entries()) {
  exact(item, ['name','temperature','unit','value','sampleCount','comparison','budget','passed','source'], `$.measurements[${index}]`);
  const key = `${item.name}:${item.temperature}`;
  const budget = expected.get(key);
  if (!budget || seen.has(key)) { errors.push(`${key} is unexpected or duplicated`); continue; }
  seen.add(key);
  if (item.unit !== budget.unit || item.comparison !== budget.comparison || item.budget !== budget.value) errors.push(`${key} does not use the pinned budget`);
  if (!Number.isFinite(item.value) || item.value < 0 || !Number.isInteger(item.sampleCount) || item.sampleCount < 1) errors.push(`${key} has invalid samples`);
  const passed = budget.comparison === 'max' ? item.value <= budget.value : item.value >= budget.value;
  if (item.passed !== passed) errors.push(`${key} pass status is inconsistent with its measured value`);
  if (!passed) errors.push(`${key} exceeds its fixture budget`);
  if (typeof item.source !== 'string' || !item.source.includes('hermetic fixture')) errors.push(`${key} must identify fixture scope`);
}
for (const key of expected.keys()) if (!seen.has(key)) errors.push(`${key} is missing`);
if (errors.length) { console.error(errors.map(error => `- ${error}`).join('\n')); process.exit(1); }
console.log(`performance evidence valid: ${seen.size} fixture-scoped measurements`);
